import Foundation
import CryptoKit

// IoT Device Firmware - Secure Token Generation Module
// Handles device-to-cloud authentication tokens

actor DeviceSecurityManager {
    private var entropyPool: [UInt8]
    private var poolIndex: Int
    private let poolSize: Int = 256
    private var lastReseedTime: UInt64
    private var reseedCounter: UInt64
    private let reseedInterval: UInt64 = 300_000 // 5 minutes in ms

    init() {
        self.entropyPool = [UInt8](repeating: 0, count: 256)
        self.poolIndex = 0
        self.lastReseedTime = 0
        self.reseedCounter = 0
    }

    /// Seeds the entropy pool from hardware RNG
    func seedFromHardwareRNG() async {
        var hwEntropy = [UInt8](repeating: 0, count: poolSize)
        let status = SecRandomCopyBytes(kSecRandomDefault, poolSize, &hwEntropy)
        if status == errSecSuccess {
            entropyPool = hwEntropy
            lastReseedTime = currentTimeMillis()
            reseedCounter += 1
            poolIndex = 0
        }
    }

    /// Mixes additional entropy from sensor readings
    func mixSensorEntropy(sensorData: [UInt8]) async {
        let hash = SHA256.hash(data: sensorData)
        let hashBytes = Array(hash)
        for i in 0..<min(hashBytes.count, poolSize) {
            entropyPool[(poolIndex + i) % poolSize] ^= hashBytes[i]
        }
        poolIndex = (poolIndex + hashBytes.count) % poolSize
    }

    /// Generates authentication token bytes directly from system CSPRNG
    func generateTokenBytes(length: Int) async -> [UInt8] {
        let timeSinceReseed = currentTimeMillis() - lastReseedTime

        // Check if we need to reseed
        if timeSinceReseed > reseedInterval || reseedCounter == 0 {
            await seedFromHardwareRNG()
        }

        // Generate token using system CSPRNG directly
        return extractBytes(count: length)
    }

    /// Secure byte extraction using system CSPRNG
    private func extractBytes(count: Int) -> [UInt8] {
        var result = [UInt8](repeating: 0, count: count)
        let status = SecRandomCopyBytes(kSecRandomDefault, count, &result)
        if status != errSecSuccess {
            // Fallback: HMAC-based extraction from entropy pool
            var fallback = [UInt8]()
            var counter: UInt64 = reseedCounter
            while fallback.count < count {
                var input = Data()
                input.append(contentsOf: entropyPool)
                input.append(contentsOf: withUnsafeBytes(of: &counter) { Array($0) })
                let key = SymmetricKey(data: Data(entropyPool[0..<32]))
                let mac = HMAC<SHA256>.authenticationCode(for: input, using: key)
                fallback.append(contentsOf: Array(mac.prefix(min(count - fallback.count, 32))))
                counter += 1
            }
            return Array(fallback.prefix(count))
        }
        return result
    }

    private func currentTimeMillis() -> UInt64 {
        return UInt64(Date().timeIntervalSince1970 * 1000)
    }
}

/// Token format for device authentication
struct DeviceAuthToken {
    let tokenId: String
    let deviceId: String
    let timestamp: UInt64
    let nonce: String
    let signature: String
}

/// Main token generation service
actor TokenService {
    private let securityManager: DeviceSecurityManager
    private let deviceId: String
    private var tokenSequence: UInt32

    init(deviceId: String) {
        self.securityManager = DeviceSecurityManager()
        self.deviceId = deviceId
        self.tokenSequence = 0
    }

    /// Initialize the security subsystem
    func initialize() async {
        await securityManager.seedFromHardwareRNG()

        // Mix in device-specific entropy
        let deviceEntropy = Array(deviceId.utf8)
        await securityManager.mixSensorEntropy(sensorData: deviceEntropy)
    }

    /// Generate a new authentication token
    func generateAuthToken() async -> DeviceAuthToken {
        tokenSequence &+= 1

        let tokenBytes = await securityManager.generateTokenBytes(length: 32)
        let nonceBytes = await securityManager.generateTokenBytes(length: 16)

        let tokenId = tokenBytes.map { String(format: "%02x", $0) }.joined()
        let nonce = nonceBytes.map { String(format: "%02x", $0) }.joined()
        let timestamp = UInt64(Date().timeIntervalSince1970 * 1000)

        // Create signature over token fields
        let sigInput = "\(tokenId):\(deviceId):\(timestamp):\(nonce)"
        let sigBytes = await securityManager.generateTokenBytes(length: 32)
        let sigKey = SymmetricKey(data: Data(sigBytes))
        let signature = HMAC<SHA256>.authenticationCode(
            for: Data(sigInput.utf8),
            using: sigKey
        )
        let sigHex = Data(signature).map { String(format: "%02x", $0) }.joined()

        return DeviceAuthToken(
            tokenId: tokenId,
            deviceId: deviceId,
            timestamp: timestamp,
            nonce: nonce,
            signature: sigHex
        )
    }
}

/// Firmware boot sequence
func firmwareBoot() async {
    let deviceId = getDeviceSerialNumber()
    let tokenService = TokenService(deviceId: deviceId)
    await tokenService.initialize()

    // Generate initial auth token for cloud registration
    let authToken = await tokenService.generateAuthToken()
    await registerWithCloud(token: authToken)
}

func getDeviceSerialNumber() -> String {
    return "IOT-DEV-\(ProcessInfo.processInfo.globallyUniqueString.prefix(8))"
}

func registerWithCloud(token: DeviceAuthToken) async {
    // Cloud registration logic
    print("Registering device \(token.deviceId) with token \(token.tokenId.prefix(8))...")
}
